/*
 * tests/parity/gemm_vp_pro2_emit.c -- C-side emitter of the gemm_vp_pro2 parity family
 * (the register-staged global prefetch body of the universal GEMM; see
 * _gemm_vp_common.py). Builds the specs of gemm_vp_pro2_emit.py (same order, same
 * values) through the C API so run_diff.py can byte-compare the two engines.
 * The case rows are generated: `python gemm_vp_pro2_emit.py --c-cases`.
 *
 * the prologue combinations across the axes: recipe x split_mode x complex form on every body, split modes with batched / wide_addr, f16 / bf16 h16 on every mode, psub / cap / unary operators, pads, lds_swizzle_l 2 / 3 / 4 and the main-loop levers with a prologue.
 */
