    int tile[9]; /* tile_m, tile_n, tile_k, warp_m, warp_n, warp_k, warp_tile_m/n/k */
    int block_size;
    const char* trait; /* "field=value,..." (non-default TraitSpec fields) */
    const char* pro; /* "field=value,..." of the Prologue, or NULL (none) */
